prompt --application/pages/page_00002
begin
wwv_flow_imp_page.create_page(
 p_id=>2
,p_name=>'Photo Metadata Details'
,p_alias=>'PHOTO-METADATA-DETAILS'
,p_step_title=>'Photo Metadata Details'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Seite: begrenzt die Detailseite auf eine gut lesbare Breite. */',
'#exif-details {',
'    margin-inline: auto;',
'    max-inline-size: 82rem;',
'}',
'',
unistr('/* Seite: versteckt die \00E4u\00DFere technische Regions\00FCberschrift der Detailseite. */'),
'#exif-details > .t-Region-header {',
'    display: none;',
'}',
'',
'/* Alle sichtbaren Kartenregionen: einheitlicher grauer Header. */',
'#exif-photo .t-Region-header,',
'#exif-data .t-Region-header,',
'#exif-map .t-Region-header,',
'#google-ai-analysis .t-Region-header {',
'    background: #f1f3f5;',
'    border-block-end: 1px solid rgba(31, 41, 55, .14);',
'}',
'',
'/* Alle sichtbaren Kartenregionen: einheitlicher fetter Titel. */',
'#exif-photo .t-Region-title,',
'#exif-data .t-Region-title,',
'#exif-map .t-Region-title,',
'#google-ai-analysis .t-Region-title {',
'    font-weight: 700;',
'    letter-spacing: 0;',
'    text-transform: none;',
'}',
'',
unistr('/* Region Photo: setzt Innenabstand f\00FCr das Bild und die Foto-Felder. */'),
'#exif-photo .t-Region-body {',
'    padding: 1.25rem;',
'}',
'',
'#exif-photo .t-Form-fieldContainer {',
'    margin-block-end: 1rem;',
'}',
'',
'/* Region Photo: entfernt Zusatzabstand um das Foto-Item. */',
'#P2_PHOTO_CONTAINER {',
'    margin-block: 0;',
'}',
'',
unistr('/* Region Photo: rundet Foto und Container gleichm\00E4\00DFig ab. */'),
'#P2_PHOTO,',
'#P2_PHOTO_CONTAINER .t-Form-inputContainer,',
'#P2_PHOTO_CONTAINER .display_only {',
'    border-radius: 18px;',
'    overflow: hidden;',
'}',
'',
'/* Region Photo: zeigt das Bild kompakt, ohne es zu beschneiden. */',
'#P2_PHOTO img {',
'    background: #ffffff;',
'    border: 0;',
'    border-radius: 18px;',
'    box-shadow: none;',
'    clip-path: inset(0 round 18px);',
'    display: block;',
'    inline-size: auto;',
'    margin-inline: auto;',
'    max-inline-size: 100%;',
'    object-fit: contain;',
'}',
